from ..base import BaseInterface


class BaseRemoteInterface(BaseInterface):
    def _execute_base_remote_operation(self, operation, params, config, trs_ip, flags, alias):
        remote_executor = self.command_store.get(alias)
        return remote_executor.execute_command(alias=alias, operation=operation, params=params, filepath=None,
                                               log_path=config.log_path, trs_ip=trs_ip, host_ip=config.host_ip, flags=flags)
